    'exif-viewer': { about: 'EXIF Metadata Viewer inspects metadata actually present in an uploaded image, creates a JSON report, and can include a canvas-rendered PNG copy without the source metadata.', input: ['Images containing supported EXIF metadata'], output: ['ZIP', 'JSON metadata report', 'Metadata-free PNG when selected'], quality: 'The optional clean copy is decoded and re-encoded as PNG. Visible pixels are retained through canvas rendering, but color profiles, animation, and source encoding details may change.', features: [['Metadata inspection', 'List supported camera, capture, and GPS fields that are present.'], ['JSON report', 'Save detected tags in a structured file.'], ['Clean-copy option', 'Include a re-encoded PNG without original EXIF fields.']], uses: [['Privacy review', 'Check whether an image contains location or camera data before sharing.'], ['Capture inspection', 'Review recorded date, equipment, and exposure fields when available.']], limits: ['Not every metadata block or vendor-specific tag is parsed.', 'Absence from the report is not a forensic guarantee that all hidden data is absent.', 'The PNG clean copy may be larger than a source JPEG.'], related: ['compress-image', 'resize-image', 'color-extractor', 'background-remover'] }
