    'gif-maker': ['GIF Maker', 'encodes a sequence of browser-decodable images as an animated GIF', ['JPG', 'JPEG', 'PNG', 'WEBP and browser-decodable still images'], ['GIF'], ['GIF uses an indexed palette, so gradients and photographic colors can be reduced.', 'Large frames, many images, and short delays increase memory use and output size.'], ['gif-to-png', 'resize-image', 'compress-image']],
