    'pdf-to-epub': ['PDF to EPUB', 'extracts readable PDF text into a reflowable EPUB package', ['PDF'], ['EPUB'], ['Exact page layout, columns, and images are not reconstructed.', 'Scanned PDFs need OCR before useful text can be extracted.'], ['epub-to-pdf', 'pdf-to-text', 'pdf-to-html']],
    'excel-to-pdf': ['Excel to PDF', 'renders workbook cells as readable PDF tables', ['XLSX', 'XLS', 'CSV'], ['PDF'], ['Print areas, charts, macros, formulas, and native Excel pagination are not reproduced.', 'Large sheets are limited by the browser cell budget.'], ['pdf-to-excel', 'txt-to-pdf', 'merge-pdf']],
    'ppt-to-pdf': ['PPT to PDF', 'renders supported PPTX slide content into one PDF page per slide', ['PPTX'], ['PDF'], ['Legacy PPT is unsupported.', 'Custom fonts, charts, SmartArt, themes, animations, media, gradients, and master-slide effects may simplify or be omitted.'], ['pdf-to-ppt', 'image-to-pdf', 'pdf-to-image']],
    'pdf-to-text': ['PDF to Text', 'extracts selectable character data from PDF pages into plain text', ['PDF'], ['TXT'], ['Scanned pages require OCR.', 'Visual layout, images, and typography are not preserved.'], ['ocr-pdf', 'pdf-to-word', 'pdf-to-markdown']],
