    'pdf-to-markdown': ['PDF to Markdown', 'extracts PDF text into a Markdown-oriented document for further editing', ['PDF'], ['Markdown'], ['Heading, list, table, and column semantics may not be recoverable from PDF coordinates.', 'Scanned pages require OCR.'], ['markdown-to-pdf', 'pdf-to-text', 'pdf-to-html']],
    'image-to-pdf': ['Image to PDF', 'assembles supported image files into a PDF with one fitted page per image', ['JPG', 'JPEG', 'PNG', 'WEBP'], ['PDF'], ['Images remain raster content and are not automatically OCRed.', 'Large source dimensions increase memory and output size.'], ['jpg-to-pdf', 'png-to-pdf', 'ocr-pdf']],
    'png-to-pdf': ['PNG to PDF', 'places PNG images onto PDF pages for consistent document sharing', ['PNG'], ['PDF'], ['Transparency is composited for PDF output and may appear different against the page background.', 'The result is image-based.'], ['image-to-pdf', 'jpg-to-pdf', 'pdf-to-png']],
    'txt-to-pdf': ['TXT to PDF', 'paginates plain text into a downloadable PDF', ['TXT'], ['PDF'], ['Plain text contains no source typography, images, or complex layout to preserve.', 'Very long lines are wrapped by the renderer.'], ['pdf-to-text', 'markdown-to-pdf', 'word-to-pdf']],
    'pdf-to-image': ['PDF to Image', 'renders PDF pages as downloadable raster images', ['PDF'], ['Image files'], ['Text becomes pixels and is no longer selectable.', 'Resolution affects sharpness, memory, and file size.'], ['pdf-to-png', 'pdf-to-jpg', 'extract-images-pdf']],
