  add('zip-manager', 'ZIP Manager packages the files you select into one downloadable ZIP archive. It is useful when several documents, images, or project assets need to travel together without changing their individual file contents.', [['Multiple-file packaging', 'Add several files to one archive.'], ['Custom archive name', 'Choose the ZIP filename before creating it.'], ['Browser-local output', 'JSZip creates the downloadable archive in the current browser session.']], ['Add the files you want to package.', 'Review the selected files and set the archive name.', 'Choose Create ZIP.', 'Download the generated archive and keep the source files until you verify it.'], [['Email handoff', 'Bundle several attachments into one file for a recipient.'], ['Project sharing', 'Group selected assets or documents into one archive for transfer.']], ['Multiple selected files'], ['ZIP archive'], ['The current interface adds selected files by their filenames; it does not provide folder-creation controls.', 'Already compressed media and archives may not become materially smaller.', 'Large file sets are limited by available browser memory.'], 'Select five related project files, name the output project-files.zip, create it, and verify the archive contains all five files before sending it.', ['Use a descriptive archive name and retain originals.', 'Inspect archive contents before sharing sensitive or executable files.'], ['zip-extractor', 'hash-tool', 'password-generator'], [['Does ZIP always reduce file size?', 'No. JPG, video, existing ZIP files, and other compressed formats may show little reduction.'], ['Can I add more than one file?', 'Yes. The selected files are packaged into one ZIP download.'], ['Are files changed when packaged?', 'The tool packages the selected file data; verify important archives after creation.']], 'JSZip writes the selected files into a standard ZIP container in the browser. It does not promise a particular compression ratio or password protection.');
  content['zip-manager'].howItWorks = 'JSZip writes the selected files into a standard ZIP container in the browser. It does not promise a particular compression ratio or password protection.';

  add('zip-extractor', 'ZIP Extractor reads one ZIP archive, lists its non-folder entries, and lets you save extracted files individually. It is intended for inspecting and retrieving files from ordinary readable ZIP packages.', [['Archive entry listing', 'Show each non-directory entry after extraction.'], ['Individual downloads', 'Save an extracted file by its listed entry.'], ['Browser-local reading', 'JSZip reads archive bytes in the current browser session.']], ['Select one ZIP file.', 'Choose Extract ZIP and wait for archive entries to load.', 'Review the listed file names and sizes.', 'Save the individual files you need.'], [['Downloaded archive review', 'Inspect a ZIP received from a trusted source before retrieving its contents.'], ['Selective retrieval', 'Download one needed item rather than repackaging the whole archive.']], ['ZIP'], ['Individual extracted files'], ['Password-protected or unsupported ZIP compression methods may fail to open.', 'Corrupt archives can fail during parsing or extraction.', 'The current interface skips directory entries and does not provide a download-all archive action.'], 'Open a ZIP with images and text files, review the entry list, and save only the needed document.', ['Treat archives from untrusted sources carefully, especially executable content.', 'Keep the source ZIP until all required files have been saved and verified.'], ['zip-manager', 'hash-tool', 'password-generator'], [['Can I extract one file?', 'Yes. Each listed non-folder entry has its own Save action.'], ['Can this open password-protected ZIP files?', 'The current interface does not provide a password entry flow, so encrypted archives may not open.'], ['Are folders shown as files?', 'Directory entries are skipped; listed file names can still include their archive path.']], 'JSZip parses the selected ZIP in the browser and exposes each non-directory entry as a Blob for individual download. The interface does not write files directly to your disk.');
  content['zip-extractor'].howItWorks = 'JSZip parses the selected ZIP in the browser and exposes each non-directory entry as a Blob for individual download. The interface does not write files directly to your disk.';

  // Phase 4 editorial revisions. Keep engine limits/formats beside existing entries;
  // these replace introductory/instructional copy, not processing implementations.
  const revise = (id, about, steps, questions, example, tips) => {
    Object.assign(content[id], {
      about,
      faqs: questions.map(([question, answer]) => ({ question, answer })),
      examples: [example], tips,
      editorialStatus: 'AI-assisted draft; human editorial review pending'
    });
    setSteps(id, steps);
  };
  revise('merge-pdf', [
    'A cover letter, report and appendix can travel as one PDF without converting their pages into pictures. Merge PDF copies complete documents in queue order; the page sequence within each source stays together.',
    'Decide the file order before merging. If you need only three pages from a long attachment, extract those pages first. Merging is document assembly, not compression, redaction or verification of signatures.'
  ], ['Select the PDFs that belong in the final packet; leave unrelated attachments out of the queue.', 'Move the cover, body and appendix into reading order using the file-card reorder controls.', 'Merge the ordered queue; an unreadable or encrypted source may prevent completion.', 'Open the downloaded document and check the transitions between files as well as the total page count.'], [
    ['Will merging blur small print?', 'The merge copies page objects instead of taking screenshots. Original raster scans remain limited by their source resolution.'],
    ['Why does a protected attachment stop the merge?', 'The browser PDF parser needs readable page objects. Unlock only files you are authorized to access, then retry with the readable copy.'],
    ['Do bookmarks and signatures prove the merged file is unchanged?', 'No. A new PDF is written; do not assume document-level bookmarks, forms or cryptographic signatures retain their original behavior.']
  ], 'A two-page letter followed by a twelve-page report and a three-page appendix produces 17 pages. Check pages 2–3 and 14–15 to verify the joins.', ['Retain the separately signed original when signature validity matters.', 'For a page-level rearrangement, open the result in Organize PDF.']);
  revise('split-pdf', [
    'Separate a long PDF into deliverables using physical page ranges or individual-page output. A range describes positions in the file, not the page numbers printed in the footer: a cover and contents page can shift those positions.',
    'Choose splitting when you need several independent PDFs. Use Extract PDF Pages instead when the intended result is one document containing a selected subset.'
  ], ['Open the source PDF and count any cover or contents pages before the numbered body.', 'Select individual pages for one sheet per output, or range mode for chapters.', 'Enter the required physical ranges and confirm that every endpoint exists.', 'Download the results and inspect the first and last page of each section.'], [
    ['Why is printed page 1 not physical page 1?', 'Front matter can appear before the numbered body. Use the preview order rather than printed labels when entering a range.'],
    ['How do I group non-contiguous or repeated pages?', 'Use semicolons to separate files and commas within each file: 3,1,1;2-4 creates two outputs. Without semicolons, each comma-separated range makes its own output.'],
    ['Which tool makes one combined subset?', 'Extract PDF Pages keeps the chosen pages together. Split PDF is intended to create separate deliverables.']
  ], 'A manual has two introductory pages before chapter one. If the chapter occupies physical pages 3–8, enter that range even when the printed footer starts at 1.', ['Check section boundaries before distributing confidential material.', 'Keep the original as the reference for missing-page checks.']);
  revise('compress-pdf', [
    'PDF size is not determined by page count alone. A short scan can contain more image data than a long text document. This compressor uses qpdf in a browser worker: Low targets structure and streams, while Balanced and High can also recompress eligible raster images.',
    'The tool measures the result rather than promising a percentage saving. It does not reduce image pixel dimensions. An already efficient PDF can legitimately produce no smaller download.'
  ], ['Choose a readable, unencrypted PDF within the displayed 25 MB limit.', 'Start with Low for quality-sensitive artwork, or Balanced for an image-heavy document.', 'Run compression and compare the measured original and resulting byte sizes.', 'If a smaller copy is offered, inspect fine print, images, links and forms before replacing any working copy.'], [
    ['Why did a large PDF produce no savings?', 'Its streams and pictures may already be efficiently encoded. Rewriting the same information can add overhead rather than remove it.'],
    ['Does High make the pages lower resolution?', 'This workflow does not downsample dimensions. Stronger eligible image recompression can still introduce visible artifacts.'],
    ['Can I preserve a signed original by choosing Low?', 'Low avoids deliberate lossy image recompression, but rewriting the document normally invalidates a cryptographic signature. Keep the original signed file.']
  ], 'For a scanned report, compare the text edges in Low and Balanced outputs at the same zoom. Choose the smaller acceptable copy only after comparing the measured sizes; High is not automatically the best choice.', ['Use the smallest acceptable file, not the most aggressive setting by default.', 'Compression is not removal of hidden text, attachments or personal metadata.']);
  revise('pdf-to-jpg', [
    'Turn complete PDF pages into raster pictures when a destination accepts images rather than documents. The renderer captures page appearance, including text and diagrams; it does not extract the original photo objects embedded inside the PDF.',
    'The workspace supports JPG and PNG output. JPG is useful for photographic pages, while PNG avoids JPEG artifacts around small text and line work. More render pixels increase memory use and may increase the download size.'
  ], ['Select the PDF and confirm that the preview opens correctly.', 'Choose JPG or PNG and review the page selection and rendering settings exposed by the workspace.', 'Render the requested pages; keep the tab open while large pages are processed.', 'Inspect the generated page images and save the download, checking that the required pages are included.'], [
    ['Will I be able to select text in the image?', 'No. Letters become pixels. Keep the PDF or use PDF to Text if selectable wording is the goal.'],
    ['Why does the image look soft after enlarging it?', 'Raster output contains a fixed number of pixels. Enlarging it later cannot restore vector detail; render at a suitable size before export.'],
    ['Can an encrypted PDF always be rendered?', 'No. The document must be readable by the PDF engine; use an authorized unlocked copy when password protection prevents loading.']
  ], 'For a three-page brochure destined for a slide deck, render three page images, then compare page edges and small captions at their intended slide size.', ['Choose Extract Images PDF if you need embedded pictures without page furniture.', 'A scanned page can be rendered, but this does not improve its original scan detail.']);
  revise('jpg-to-pdf', [
    'Package photographs or receipt scans as a document with one image-based page per selected file. Despite the route name, the supported queue also accepts PNG and WebP. The page content remains a picture rather than editable document text.',
    'Review orientation and order before export. A PDF container makes the collection easier to share, but it does not prove that the photos are authentic or that small photographed writing is legible.'
  ], ['Choose the receipt or photograph files to include in the packet.', 'Arrange their cards in the intended sequence and remove accidental duplicates.', 'Review the page-fitting settings and any source image that appears sideways.', 'Create the PDF, then reopen it to check one page per image and readable detail.'], [
    ['Does a phone photograph become a scan with searchable text?', 'No. The photo is embedded as raster content. OCR PDF separately offers a TXT transcript or rasterized searchable PDF; recognition must be proofread.'],
    ['Why is the PDF larger than expected?', 'High-resolution pictures can dominate document size. Consider resizing oversized originals for the destination before assembling them.'],
    ['Can I combine a receipt PDF with the photographs?', 'First convert the photographs to PDF here, then combine that result with the existing document using Merge PDF.']
  ], 'Arrange five receipt photos chronologically, create the PDF, and check that page five is the final receipt rather than a duplicate of page one.', ['Keep readable originals for expense verification.', 'Do not use OCR output as the only record of monetary values.']);
  content['jpg-to-pdf'].tips = ['Rotate incorrect source images before assembly.', 'OCR PDF can export a TXT transcript or a rasterized PDF with recognized searchable text.'];
  revise('image-to-pdf', [
    'Bring mixed JPG, PNG and WebP images into a single PDF for a recipient who needs one document. Each selected image contributes a fitted page, so the file queue determines the narrative order.',
    'This is image packaging, not reconstruction of a Word document. A screenshot of a table stays a screenshot; text recognition and spreadsheet extraction are different tasks.'
  ], ['Add the supported pictures that form the document, including mixed formats if needed.', 'Review the thumbnails and place the images in the sequence a recipient should read.', 'Set the available page options, considering whether wide screenshots will be readable.', 'Build the PDF and inspect its page count, margins and smallest lettering.'], [
    ['Should I use this or JPG to PDF?', 'Both assemble image-based pages. This route is a convenient entry point for a mixed-format collection rather than a different OCR engine.'],
    ['Can I edit the pictured table after conversion?', 'Not as native PDF text or spreadsheet cells. The original picture is the content of the page.'],
    ['Does PDF packaging retain animation?', 'No. This document workflow creates static pages; it is not an animated-image container.']
  ], 'Combine a PNG diagram, a JPG field photo and a WebP screenshot into a three-page inspection packet. Check that the wide screenshot remains readable on its fitted page.', ['Crop irrelevant screen margins before packaging screenshots.', 'Use Merge PDF to attach an already-existing PDF to the resulting packet.']);
  revise('compress-image', [
    'Reduce image delivery size by re-encoding its pixels. This tool keeps the image dimensions and uses the selected browser encoder; the quality control matters for lossy JPG/WebP encoding, not as a universal percentage reduction in file size.',
    'PNG output preserves transparency and uses lossless encoding, so moving a quality slider may not reduce it. JPG cannot retain alpha transparency: this compressor draws transparent areas onto white before JPEG export.'
  ], ['Choose an image and note its starting dimensions and file size.', 'Select the output format appropriate for a photograph, sharp graphic or transparent asset.', 'Adjust lossy quality where applicable and process a comparison copy.', 'Inspect edges, gradients and transparent areas at full size, then download only an acceptable result.'], [
    ['Does 70% quality mean 30% fewer bytes?', 'No. Encoder quality is not a size percentage. Results depend on picture detail, source compression and browser encoding.'],
    ['Why did a PNG barely shrink?', 'PNG is lossless, and canvas encoding does not provide a JPEG-style quality tradeoff for it. Try reducing unnecessary dimensions in Resize Image.'],
    ['What happens to a transparent logo saved as JPG?', 'This compressor places it over white because JPEG has no alpha channel. Use PNG or supported WebP output to retain transparency.']
  ], 'Compare a photo at two JPG quality settings at 100% zoom. If both look acceptable, keep the smaller measured result; repeat with a text screenshot and look for halos around letters.', ['Avoid repeatedly recompressing already-lossy downloads.', 'Use Resize Image when the actual problem is excessive pixel dimensions.']);
  revise('resize-image', [
    'Change pixel dimensions for a form, web image or document illustration. Resizing changes the sampling grid; cropping changes the pictured area. Use the aspect-ratio lock when the subject must keep its proportions.',
    'A larger width does not recover detail missing from the original. When a destination specifies both width and height with a different shape, crop to that shape first rather than stretching a face or product.'
  ], ['Select the source and check its current width and height.', 'Keep the aspect ratio locked for proportional scaling, or deliberately choose independent dimensions.', 'Enter the destination pixel dimensions or the available percentage scale.', 'Resize, inspect the output dimensions and subject proportions, and download the result.'], [
    ['Why does changing width also change height?', 'With aspect ratio locked, the second dimension is calculated from the original proportions. That prevents stretching.'],
    ['Does increasing size make a blurry photo sharp?', 'No. The browser interpolates existing pixels; it cannot restore detail that was never captured.'],
    ['How do I meet a square upload requirement?', 'Crop the picture to a square first, then resize the square to the required pixel dimensions.']
  ], 'A 2400 × 1600 photo resized proportionally to 1200 pixels wide becomes 1200 × 800. A 1200 × 1200 requirement needs a square crop, not an unlocked stretch.', ['Confirm whether the destination asks for pixels or a maximum byte size.', 'Retain the full-resolution original for later print use.']);
  revise('crop-image', [
    'Choose which part of a photograph survives the export. Free crop gives arbitrary framing; an aspect-ratio preset keeps a required shape while you move or resize the selection. The pixel fields provide a more exact boundary than judging the preview alone.',
    'The browser preview is scaled for the screen, but export coordinates refer to the decoded image. Inspect the downloaded dimensions rather than treating the on-screen rectangle as the number of output pixels.'
  ], ['Select the picture and choose free framing or the aspect ratio required by the destination.', 'Move and resize the selection around the subject; zoom or pan the view to inspect fine edges.', 'Open exact position and size controls when the crop needs a specific pixel boundary.', 'Select an offered output format, set quality where supported, then crop and inspect the downloaded file.'], [
    ['Does a square preset decide my final pixel size?', 'It constrains shape. The selected rectangle still determines how many source pixels are retained; use Resize Image afterward if a fixed destination size is needed.'],
    ['Does zooming the editor crop the file?', 'No. Zoom changes the view. The crop rectangle and its image-space coordinates determine the exported region.'],
    ['Which output should I use for transparent content?', 'Choose an alpha-capable format such as PNG. JPG cannot retain transparency; check the background in the exported preview before sharing.']
  ], 'Frame a portrait as a square while keeping the eyes away from the top edge. Export the crop, check its dimensions, then resize that result for the profile-image requirement.', ['Do not crop through fine subject details merely because the mobile preview is small.', 'Higher lossy quality cannot restore areas removed by cropping.']);
  revise('image-converter', [
    'Use Image Converter when a destination requires a different image encoding, not merely a renamed extension. The converter inspects source bytes, decodes the picture and enables only outputs supported by the current browser and available codecs.',
    'Format conversion can change alpha transparency, animation, metadata and color interpretation. Compare the decoded result with the original before replacing an asset in a website, document or archive.'
  ], ['Choose the source image and wait for format detection and the original preview.', 'Select one of the genuinely enabled output formats rather than renaming the source suffix.', 'Review available quality, dimensions and background controls for that output.', 'Convert and inspect the actual output preview, size and format before downloading.'], [
    ['Why is an output option unavailable on this device?', 'Encoding support is detected at runtime. A format is not offered as working merely because its name is known.'],
    ['Is changing .png to .jpg equivalent?', 'No. A filename extension does not change the encoded bytes. This workflow decodes and re-encodes the image.'],
    ['Can I assume all metadata and animation survive?', 'No. Treat conversion as a new image export and review the route-specific limitations, especially for animated and metadata-dependent files.']
  ], 'Convert a transparent PNG badge for a service that accepts only JPG. Choose a suitable background and inspect the edges; the output cannot carry the original alpha channel.', ['Preserve a master in the original format.', 'Test the exported file in the receiving application as well as the preview.']);
  revise('image-ocr', [
    'Recover a text transcript from a JPG, JPEG, PNG or WebP image containing printed text. Select English, Spanish, French, German, or Hindi; the browser loads the OCR engine and selected language data, then recognizes the selected image locally.',
    'The transcript is an interpretation, not a certified copy. Small characters, skew, glare and handwriting can change names or numbers. Compare the recognized text with the picture before relying on it.'
  ], ['Select a supported image and the language of its printed text.', 'Keep Original preparation first; optionally compare contrast or adaptive thresholding and correct rotation.', 'Start recognition and allow the engine and language model to load on first use.', 'Proofread the visible transcript, then copy it or download the text output.'], [
    ['Can I transcribe handwriting reliably?', 'This deployment is aimed at printed text. Handwriting and unusual lettering may produce incomplete or incorrect text.'],
    ['Does the output preserve the document layout?', 'The result is text, not a faithful reconstruction of columns, tables or typography. Check reading order as well as spelling.'],
    ['Why is the first run slower than later runs?', 'The OCR library and trained language data must be loaded before recognition can start. A blocked dependency can prevent processing.']
  ], 'Recognize a clear invoice photo, then compare its date, invoice number and every total character by character. Correct the transcript before placing values in an accounting system.', ['Never treat confidence or a successful download as proof of accuracy.', 'Preprocessing can remove faint details; compare results with Original preparation.']);
  revise('background-remover', [
    'Make a foreground cutout, then correct the mask before export. Automatic segmentation is a starting point: hair, transparent objects, shadows and similar foreground/background colors often need manual attention.',
    'The dedicated editor keeps the source image and an editable mask. Erase removes unwanted mask areas; Restore brings back parts removed by the automatic pass. Inspect edges against more than one background before saving.'
  ], ['Open an image in the Background Remover editor and allow required model assets to load.', 'Run the automatic pass, then zoom into subject edges rather than judging only the fitted preview.', 'Use Erase, Restore and refinement controls to correct the mask where needed.', 'Choose the background and export settings, then inspect the downloaded cutout at its intended size.'], [
    ['Why is part of my subject missing?', 'Segmentation predicts foreground from image content and can misclassify similar colors or fine structures. Restore the missing mask area manually.'],
    ['Does a white preview mean the file is transparent?', 'Not necessarily. Select the transparent export option and an alpha-capable format, then verify the result on a contrasting background.'],
    ['Will every phone process the same image size?', 'No. Model initialization, available memory and browser capabilities affect practical limits; a smaller source may be needed on constrained devices.']
  ], 'Cut out a product photographed on a pale desk. Inspect pale edges on a dark background, restore any lost rim and erase desk remnants before exporting.', ['Keep an untouched source so a mask can be revised later.', 'Do not use a cutout as evidence that a photograph was captured against the exported background.']);
  revise('barcode-generator', [
    'Encode text or a destination address into a QR image for scanning. The pattern carries the entered payload; it is not an account-backed redirect service, a scan counter or proof that a linked website is safe.',
    'Use a short, final payload and test the saved code at its real display or print size. A dense code scaled too small can fail even when it looks sharp on a large monitor.'
  ], ['Enter the exact text or complete URL the scanner should receive.', 'Generate the code and inspect its contrast and surrounding clear margin.', 'Save the offered image output without cropping away the code border.', 'Scan that exported image with the intended phone or reader and compare the decoded payload.'], [
    ['Can I change the destination after printing?', 'The generated pattern encodes the original value. Changing that value requires a new code unless the URL itself points to a redirect service you control.'],
    ['Does the code record how many people scan it?', 'This generator does not provide a scan-analytics backend. A destination website may have its own analytics.'],
    ['Why should I scan the downloaded image?', 'Export size, later resizing and print quality can affect readability independently of the browser preview.']
  ], 'Generate a code for the final public page address, save it and scan the saved image. Check the full hostname before printing labels.', ['Never encode a password merely to make it look obscure.', 'Keep the quiet border and use strong foreground/background contrast.']);
  revise('qr-reader', [
    'Read a QR payload from an uploaded picture without automatically opening the destination. The reader tries the browser BarcodeDetector where supported and falls back to the locally packaged ZXing decoder when needed.',
    'A successful decode identifies stored text, not its trustworthiness. Inspect an unfamiliar URL before visiting it. Blur, glare, missing borders or a very small symbol can prevent either decoder from reading a code.'
  ], ['Choose an image containing the complete QR symbol and its border.', 'Run recognition and wait for the native or fallback decoder.', 'Review the returned text as untrusted input, especially if it contains a link.', 'Copy the payload only after checking it; try a clearer source if no code is found.'], [
    ['Does this require native BarcodeDetector?', 'No. The current implementation can load its local ZXing fallback when native decoding is absent or unsuccessful.'],
    ['Does decoding verify the linked site?', 'No. It only recovers the payload. Check the hostname and do not enter credentials at an unexpected destination.'],
    ['Can it recover every damaged QR image?', 'No. Missing modules, blur or clipping can exceed what the available decoder can recover. A better source is preferable to repeated retries.']
  ], 'Read a QR from a screenshot, compare the decoded hostname with the expected organization, and avoid opening it if they differ.', ['This route remains under publication review and ad-free.', 'Include the whole symbol rather than tightly cropping away its border.']);
  revise('barcode-reader', [
    'Extract a barcode value from a still image using native detection where available and a packaged ZXing fallback. Symbology support depends on the decoder; this is not a product-catalog lookup service.',
    'A decoded number does not supply a product name, price or ownership record. For linear codes, keep the full run of bars in frame with enough contrast and resolution to distinguish adjacent lines.'
  ], ['Select a clear barcode photograph or screenshot with both ends visible.', 'Run the reader and let it choose the available decoding path.', 'Compare the recovered value with any human-readable digits printed below the bars.', 'Copy the text for your own inventory workflow; retake unreadable images without glare.'], [
    ['Does reading a barcode identify the product?', 'No product database is queried by this reader. It returns the encoded value, which another authorized system may interpret.'],
    ['Which formats are guaranteed in every browser?', 'No universal native format list is promised. The native API and ZXing support differ; QR and Code 128 fallback fixtures are covered by local tests.'],
    ['Why do thin bars fail in a compressed screenshot?', 'Resizing and lossy compression can merge adjacent bars. Use an original-resolution image with a complete symbol.']
  ], 'Read a Code 128 label and compare every decoded character with the warehouse reference before using it in an inventory import.', ['This route stays noindex and ad-free pending its separate review.', 'Successful decoding does not certify a physical item as genuine.']);
  revise('json-tool', [
    'Parse valid JSON and serialize it into an indented or compact representation. Formatting makes nesting easier to inspect; minifying removes presentation whitespace. Neither action repairs an invalid document or validates it against an application schema.',
    'The implementation uses JavaScript JSON parsing. Duplicate object names and integers beyond JavaScript’s safe integer range deserve care because reserialization may not preserve their original representation.'
  ], ['Paste JSON with double-quoted property names and no comments or trailing commas.', 'Choose formatted output for inspection or compact output for transport.', 'Run the parser; if it reports an error, correct the source rather than treating it as repaired output.', 'Review the result, especially large numeric identifiers, before copying it into another system.'], [
    ['Will it fix comments or trailing commas?', 'No. These are not valid JSON for JSON.parse. Remove them deliberately in the source and parse again.'],
    ['How much indentation does formatting use?', 'The pretty-print path serializes parsed JSON with two spaces per indentation level. Minified output omits that formatting whitespace.'],
    ['Is syntax success the same as schema validity?', 'No. A valid JSON value can still lack required application fields or use the wrong types. This tool does not run a JSON Schema validator.']
  ], 'Format {"order":{"items":[1,2],"paid":false}} to inspect its nesting. Removing a closing brace should produce a parse error, not a guessed replacement object.', ['Represent identifiers that must retain every digit as strings where your data contract requires it.', 'Do not paste production tokens or private customer data into an untrusted browser session.']);
  revise('base64-tool', [
    'Convert text or file bytes to Base64, or decode a Base64 string as text. Encoding changes representation, not confidentiality: anyone with the encoded value can recover the bytes.',
    'Text input is encoded as UTF-8. The decode path displays UTF-8 text and rejects other binary data. File import encodes the selected bytes, or reads a Base64 text file in Decode mode; it does not reconstruct arbitrary binary downloads.'
  ], ['Choose text encoding, text decoding or a file to encode.', 'For decoding, supply the Base64 characters rather than an entire data-URL prefix.', 'Run the conversion and read any invalid-input error before using the output.', 'Check the decoded wording or encoded value against the intended consumer before copying it.'], [
    ['Is Base64 suitable for hiding credentials?', 'No. It is reversible encoding with no secret key. Treat encoded credentials as credentials.'],
    ['Will decoding an image restore an image download?', 'This text decoder displays UTF-8 characters. It is not a general binary-file reconstruction workflow.'],
    ['Why is the encoded value longer?', 'Base64 represents groups of three bytes with four characters, with padding where required. It is not compression.']
  ], 'The UTF-8 text Hello encodes as SGVsbG8=. Decode that value to confirm the text round trip; do not infer binary-file fidelity from this text test.', ['This route remains noindex/ad-free during review.', 'Use the alphabet and padding expected by the receiving protocol; URL-safe Base64 is a separate variant.']);
  revise('password-generator', [
    'Generate a new password from the selected character groups using browser cryptographic randomness. The generator includes a character from each selected group and shuffles the result; it is not a password manager or an account recovery service.',
    'The displayed strength estimate is a rough calculation based on length and the character pool, not a guarantee against compromise. Reuse, phishing and exposed clipboard contents can defeat an otherwise strong generated value.'
  ], ['Choose a length accepted by the target service and select its permitted character groups.', 'Generate a fresh value rather than editing a familiar password into the result.', 'Copy it into the intended password field and store it in a password manager you trust.', 'Use a different generated password for another account; regenerate if the value is exposed.'], [
    ['Will every selected character group appear?', 'The generator takes a character from each selected group before filling and securely shuffling the remaining positions.'],
    ['Does the strength label prove the password is safe?', 'No. It estimates a search space and does not know about phishing, reuse, clipboard exposure or the receiving service’s storage practices.'],
    ['Can the site recover a generated password later?', 'Do not depend on this generator for storage or recovery. Save the accepted password in your own trusted password manager.']
  ], 'For an account that permits letters, digits and symbols, select those groups and an adequate accepted length. Copy the fresh result rather than the literal sample from a tutorial.', ['Do not share a screenshot containing the generated value.', 'Enable an additional authentication factor where the service offers it.']);
  revise('gst-calculator', [
    'Separate tax from a GST-inclusive amount or add tax to a net amount using the selected arithmetic rate. The key distinction is the base: a rate applies to the net value, not directly to an already tax-inclusive total.',
    'This is an arithmetic aid, not a tax classification service. It cannot decide the legally applicable rate, eligibility for credit, exemptions, cess or whether an invoice should use IGST instead of a CGST/SGST split.'
  ], ['Decide whether your amount excludes GST or already includes it.', 'Enter the amount and choose one of the rates offered by the form.', 'Use Add for a net amount or Remove for an inclusive total.', 'Check the net, tax and gross relationship, then independently confirm the correct legal treatment.'], [
    ['Why is removing 18% not the same as subtracting 18% of the total?', 'For an inclusive total, net = gross / 1.18. The tax is gross minus net, because the original 18% was applied to net.'],
    ['Does the equal split determine my tax jurisdiction?', 'No. The displayed half CGST and half SGST is a calculation assumption, not a place-of-supply or IGST determination.'],
    ['Are the selectable rates current legal advice?', 'No. They are arithmetic options in the interface. Verify the rate and rules for the actual transaction with authoritative guidance or a qualified adviser.']
  ], 'At an assumed 18% rate, ₹1,000 net plus ₹180 tax is ₹1,180 gross. Removing that rate from ₹1,180 recovers ₹1,000 net, not ₹967.60.', ['Compare totals before and after any invoice rounding.', 'Do not infer tax eligibility from a successful calculation.']);
